questionvariables.text:
stack_include_contrib("prooflib.mac");
v : rand([5,6,8,10]);
tq : rand([3,4,5,6]);
dq : v*tq;
tmax : 8;
ymax : v*tmax + 6;
find_t_str : sconcat("Find the time \\(t=", tq, "\\) s on the horizontal (time) axis.");
proof_steps : [["find_t", find_t_str], ["up", "Move vertically up until you reach the line of best fit."], ["across", "Move horizontally across to the distance (vertical) axis and read off the value."]];
proof_steps : random_permutation(proof_steps);
ta : proof("find_t","up","across");
TrendOpts : [[optLin, true, "Linear — the points lie on a straight line."], [optNon, false, "Non-linear — the points lie on a curve."]];
